  const productionModel=typeof module==='object'&&module.exports?load("js/production_model.js"):root.SIDE_PRODUCTION_MODEL;
  const api=factory(productionModel,typeof module==='object'&&module.exports?load("js/business_rules.js"):root.SIDE_BUSINESS_RULES);
